    const UNSAFE = ['__proto__', 'prototype', 'constructor'];
    function assertSafe(o) {   // 入口递归校验键
      for (const k of Object.keys(o)) {
        if (UNSAFE.includes(k)) throw new Error('危险键: ' + k);
        if (o[k] && typeof o[k] === 'object') assertSafe(o[k]);
      }
    }
    const isAdmin = u => Object.prototype.hasOwnProperty.call(u, 'isAdmin') && u.isAdmin === true;

